mapper.select:
SELECT r.*, ctd.name AS cylinderTypeName, c.contract_no AS contractNo, u.unit_name AS unitName FROM contract_cylinder_register r LEFT JOIN cylinder_type_dict ctd ON r.cylinder_type_id = ctd.cylinder_type_id LEFT JOIN contract c ON r.contract_id = c.contract_id LEFT JOIN unit u ON c.unit_id = u.unit_id
AND r.contract_id = #{contractId}
AND r.cylinder_type_id = #{cylinderTypeId}
AND r.cylinder_no LIKE CONCAT('%', #{cylinderNo}, '%')
AND r.rfid_tag = #{rfidTag}
AND r.cylinder_status = #{cylinderStatus}
AND c.unit_id = #{unitId}
AND r.next_inspect_date < CURDATE()
AND r.next_inspect_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY)
AND (r.next_inspect_date IS NULL OR r.next_inspect_date > DATE_ADD(CURDATE(), INTERVAL 30 DAY))
ORDER BY r.registered_at DESC
